package org.jetbrains.java.decompiler.main.rels;

import org.jetbrains.annotations.Nullable;
import org.jetbrains.java.decompiler.main.collectors.CounterContainer;
import org.jetbrains.java.decompiler.modules.decompiler.flow.DirectGraph;
import org.jetbrains.java.decompiler.modules.decompiler.flow.FlattenStatementsHelper;
import org.jetbrains.java.decompiler.modules.decompiler.stats.RootStatement;
import org.jetbrains.java.decompiler.modules.decompiler.vars.VarProcessor;
import org.jetbrains.java.decompiler.modules.decompiler.vars.VarVersionPair;
import org.jetbrains.java.decompiler.struct.StructClass;
import org.jetbrains.java.decompiler.struct.StructMethod;
import org.jetbrains.java.decompiler.struct.gen.MethodDescriptor;

import java.util.*;

public class MethodWrapper {
  public final RootStatement root;
  public final VarProcessor varproc;
  public final StructMethod methodStruct;
  public final StructClass classStruct;
  public final CounterContainer counter;
  public final Set<String> setOuterVarNames = new HashSet<>();

  public DirectGraph graph;
  public List<VarVersionPair> synthParameters;
  public Throwable decompileError;
  public Set<String> commentLines = null;
  public boolean addErrorComment = false;
  public boolean isCompactRecordConstructor = false;

  public MethodWrapper(RootStatement root, VarProcessor varproc, StructMethod methodStruct, StructClass classStruct, CounterContainer counter) {
    this.root = root;
    this.varproc = varproc;
    this.methodStruct = methodStruct;
    this.classStruct = classStruct;
    this.counter = counter;

    if (root != null && root.commentLines != null) {
      for (String s : root.commentLines) {
        addComment(s);
      }
      addErrorComment |= root.addErrorComment;
    }
  }

  public @Nullable DirectGraph getOrBuildGraph() {
    if (graph == null && root != null) {
      graph = new FlattenStatementsHelper().buildDirectGraph(root);
    }

    return graph;
  }

  public void addComment(String comment) {
    if (commentLines == null) {
      commentLines = new LinkedHashSet<>();
    }

    commentLines.add(comment);
  }

  public MethodDescriptor desc() {
    return MethodDescriptor.parseDescriptor(methodStruct, null);
  }

  @Override
  public String toString() {
    return "{" + classStruct.qualifiedName + ": " + methodStruct.getName() + "}";
  }
}package org.jetbrains.java.decompiler.main.rels;

import org.jetbrains.annotations.Nullable;
import org.jetbrains.java.decompiler.modules.decompiler.ValidationHelper;
import org.jetbrains.java.decompiler.modules.decompiler.stats.RootStatement;
import org.jetbrains.java.decompiler.struct.StructMethod;
import org.jetbrains.java.decompiler.util.DotExporter;

import java.util.ArrayList;
import java.util.List;

public final class DecompileRecord {
  private final List<String> names = new ArrayList<>();
  private final StructMethod mt;
  private int mainLoopIteration = 0;
  private int mergeLoopIteration = 0;

  public DecompileRecord(StructMethod mt) {
    this.mt = mt;
  }

  public void add(String name, @Nullable RootStatement root) {
    String exportName = "";
    if (this.mainLoopIteration > 0) {
      exportName += "Loop_" + this.mainLoopIteration + "_";
    }

    if (this.mergeLoopIteration > 0) {
      exportName += "Merge_" + this.mergeLoopIteration + "_";
    }

    exportName += name;

    add(exportName);

    if (root == null) {
      return;
    }

    DotExporter.toDotFile(root, mt, "debug", exportName);

    // Ensure that code at the end of this stage is valid
    ValidationHelper.validateStatement(root);
  }

  public void add(String name) {
    this.names.add(name);
  }

  public void incrementMainLoop() {
    this.mainLoopIteration++;
  }

  public void incrementMergeLoop() {
    this.mergeLoopIteration++;
  }

  public void resetMainLoop() {
    this.mainLoopIteration = 0;
  }

  public void resetMergeLoop() {
    this.mergeLoopIteration = 0;
  }

  public List<String> getNames() {
    return names;
  }

  public void print() {
    for (int i = 0; i < this.names.size(); i++) {
      System.out.println(i + " " + this.names.get(i));
    }
  }
}

