  public void reformat() {
    if (myCurrentGroup != myRootGroup) {
      throw new IllegalStateException("Cannot reformat while in a group");
    }
    if (myHasReformatted) {
      throw new IllegalStateException("Cannot reformat twice");
    }
    myHasReformatted = true;

